using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.Json;
using Aion.GameServer.Controllers.Attack.RetailNpc;
using Xunit;
using P = Aion.GameServer.Controllers.Attack.RetailNpc.RetailNpcSpellInstantParameters;
using S = Aion.GameServer.Controllers.Attack.RetailNpc.RetailNpcPeriodicSpellParameters;
namespace Aion.GameServer.Tests;
public class RetailNpcPeriodicSpellParametersTests
{
    private static readonly JsonElement Cases=Decode(SourceBlob,"00a45a05b1759a39a37c6293e104b3266e75f7d4052c942224d3a7bcc5001b39");
    public static IEnumerable<object[]> OriginalBindings()
    {
        for(int i=0;i<Cases.GetArrayLength();i++)
            for(int j=0;j<Cases[i].GetProperty("bindings").GetArrayLength();j++)yield return [i,j];
    }
    [Theory,MemberData(nameof(OriginalBindings))]
    public void CompleteRecordsPreserveAllOriginalBindingsAndSelectOnlyActualPeriodicSlots(int record,int bindingIndex)
    {
        var item=Cases[record];var binding=item.GetProperty("bindings")[bindingIndex];
        var fields=binding.GetProperty("ordered_fields");
        int level=int.Parse(fields.EnumerateArray().Single(x=>x[0].GetString()=="skill_level")[1].GetString()!,System.Globalization.CultureInfo.InvariantCulture);
        byte[] raw=Convert.FromBase64String(item.GetProperty("raw").GetString()!);
        var original=P.ProjectSelectedSpell(raw,new(binding.GetProperty("npc_id").GetInt32(),binding.GetProperty("npc_devname").GetString()!,binding.GetProperty("ordinal").GetInt32(),level,binding.GetProperty("skill_name").GetString()!),P.RequiredPins);
        var expected=item.GetProperty("periodic");
        if(expected.ValueKind==JsonValueKind.Null){Assert.Throws<ArgumentException>(()=>S.Project(original));return;}
        var result=S.Project(original);
        int Expected(string name)=>int.Parse(expected.GetProperty(name).GetString()!,System.Globalization.CultureInfo.InvariantCulture);
        Assert.Equal(1,result.EffectIndex);Assert.Equal(Expected("effect2_effectid"),result.EffectId);
        Assert.Equal(Expected("effect2_remain1"),result.Remain1);Assert.Equal(Expected("effect2_remain2"),result.Remain2);
        Assert.Equal(Expected("effect2_checktime"),result.CheckTime);Assert.Equal(Expected("effect2_reserved8"),result.R8);Assert.Equal(Expected("effect2_reserved9"),result.R9);
        Assert.Equal(Expected("effect2_reserved11"),result.Reserved11);Assert.Equal(Expected("effect2_critical_prob_mod2"),result.CriticalProbabilityMod2);
        Assert.Equal(expected.GetProperty("effect2_type").GetString()=="Bleed"?S.Family.Bleed:S.Family.SpellAttack,result.Kind);
        Assert.Equal(expected.GetProperty("effect2_reserved10").GetString(),result.Element);
        bool noResistPresent=expected.TryGetProperty("effect2_noresist",out var noResist);
        Assert.Equal(noResistPresent,result.NoResist.SourcePresent);Assert.Equal(noResistPresent?int.Parse(noResist.GetString()!):0,result.NoResist.Value);
        Assert.Equal(noResistPresent?noResist.GetString():null,result.NoResist.RawText);
        foreach(var value in new[]{result.DurationJitter,result.MagicalDefenseGateR12,result.SharingR19,result.CriticalDamageMod1,result.CriticalDamageMod2})
        {Assert.Equal(0,value.Value);Assert.False(value.SourcePresent);Assert.Null(value.RawText);}
        Assert.Equal(expected.TryGetProperty("effect2_hop_type",out var hop)?hop.GetString():null,result.HopType);
        Assert.Equal(expected.EnumerateObject().Count(),result.OrderedEffectFields.Length);
        Assert.True(original.RawBytes.AsSpan().SequenceEqual(result.CompleteSource.RawBytes.AsSpan()));Assert.Equal(original.Binding,result.CompleteSource.Binding);
        Assert.Equal(original.OrderedBindingFields,result.CompleteSource.OrderedBindingFields);
        Assert.NotSame(original,result.CompleteSource);Assert.False(result.IsLoadedRegionObservation);
    }
    [Fact] public void MissingSelectedSourceRejectsBeforeProjection()=>Assert.Throws<ArgumentNullException>(()=>S.Project(null!));
    private static JsonElement Decode(string text, string expected)
    {
        using var source = new MemoryStream(Convert.FromBase64String(text));
        using var gzip = new GZipStream(source, CompressionMode.Decompress);
        using var output = new MemoryStream(); gzip.CopyTo(output); byte[] bytes=output.ToArray();
        Assert.Equal(expected, Convert.ToHexStringLower(SHA256.HashData(bytes)));
        using var doc=JsonDocument.Parse(bytes); return doc.RootElement.Clone();
    }

    private const string SourceBlob="";
}
